import type { Alignment, Element, MagicAbility, MoveType, Stats, Trajectory, UnitKind } from '../types';

// The 40 Summons, ten per Element, one at each Cost from 16 to 88 in steps
// of 8 (Upkeep is Cost / 8). The first 28 were generated by the Summon
// generator (rules/summongen.ts, scripts/summons.run.ts); the 12 marked
// "hand-tuned" were built from a reference and hand-tuned to price at their
// Cost. Each keeps its sprite, whose key is its id: the sprite's look sets its
// Move Types. With the balance overrides, per Element 3 are aligned: Fire and
// Earth 2 Day + 1 Night, Water and Air 1 Day + 2 Night. Names are at most 6
// letters. The comment after each row names the reference it was built from
// and the Cost the model gives it.

type Spell = Omit<Extract<MagicAbility, { kind: 'damage' | 'heal' }>, 'id'>;

type Def = [
  id: string,
  name: string,
  element: Element,
  cost: number,
  alignment: Alignment,
  role: string,
  stats: [atk: number, def: number, mp: number, mdf: number, spd: number, mov: number],
  moveTypes: MoveType[],
  attack: [range: number, trajectory?: Trajectory],
  /** null: no Magic Ability. */
  magic: Spell | null,
];

