/** Magic Ability id from its name: 'Fire Arrow' → 'fire-arrow'. */
export function abilityId(name: string): string {
  return name.toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-|-$/g, '');
}

function build([id, name, element, cost, alignment, role, s, moveTypes, [range, trajectory], magic]: Def): UnitKind {
  const stats: Stats = { atk: s[0], def: s[1], mp: s[2], mdf: s[3], spd: s[4], mov: s[5] };
  return {
    id,
    name,
    isSummoner: false,
    element,
    alignment,
    cost,
    stats,
    moveTypes,
    attack: range > 1 ? { range, trajectory: trajectory ?? 'high' } : { range },
    magic: magic ? [{ ...magic, id: abilityId(magic.name) }] : [],
    role,
  };
}

export const ELEMENTS: readonly Element[] = ['fire', 'air', 'earth', 'water'];

/** Built-in summons (before any balance overrides), Fire, Air, Earth, Water. */
export const BASE_SUMMONS: readonly UnitKind[] = ELEMENTS.flatMap((e) => DEFS.filter((d) => d[2] === e).map(build));
